fn main() {
    // Safe parsing
    let valid: i32 = "42".parse().unwrap();
    println!("Valid: {}", valid);

    // Demonstrate panicking safely
    let result = std::panic::catch_unwind(|| {
        let _: i32 = "hello".parse().unwrap();
    });
    if result.is_err() {
        println!("Error: panicked on invalid input");
    }
}
